#include <Arduino.h>

const uint8_t buttonPin = 2;
unsigned long countValue = 0;
int lastRaw = HIGH;
int stableState = HIGH;
unsigned long changedAt = 0;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  Serial.begin(9600);
  lastRaw = digitalRead(buttonPin);
  changedAt = millis();
}

void loop() {
  const unsigned long now = millis();
  const int raw = digitalRead(buttonPin);
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableState && now - changedAt >= 30) {
    stableState = raw;
    if (stableState == LOW) {
      ++countValue;
      Serial.println(countValue);
    }
  }
}
